function Logo() { return <Link to="/" className="logo" data-testid="brand-logo"><span className="logo-mark"><BrandMark size={30}/></span><span>Acolhe</span></Link>; }
function CornerLogo() {
  const location = useLocation();
  const [open, setOpen] = useState(false);
  const panelRef = useRef(null);
  const dialogRef = useRef(null);
  const triggerRef = useRef(null);
  const wasOpenRef = useRef(false);
  const isHome = location.pathname === "/";
  useEffect(() => {
    if (open) dialogRef.current?.focus({ preventScroll: true });
    if (wasOpenRef.current && !open) triggerRef.current?.focus({ preventScroll: true });
    wasOpenRef.current = open;
    if (!open) return undefined;
    const handlePointerDown = event => {
      if (!panelRef.current?.contains(event.target)) setOpen(false);
    };
    const handleKeyDown = event => {
      if (event.key === "Escape") setOpen(false);
    };
    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [open]);
  useEffect(() => {
    if (!open) return undefined;
    const dialog = dialogRef.current;
    if (!dialog) return undefined;
    const handleKeyDown = event => {
      if (event.key !== "Tab") return;
      const items = [...dialog.querySelectorAll("a[href], button:not([disabled]), input, select, textarea")];
      if (!items.length) return;
      const first = items[0];
      const last = items[items.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    dialog.addEventListener("keydown", handleKeyDown);
    return () => dialog.removeEventListener("keydown", handleKeyDown);
  }, [open]);
  useEffect(() => setOpen(false), [location.pathname]);
  if (isHome) return null;
  const close = () => setOpen(false);
  return <div className={open ? "corner-quick open" : "corner-quick"} ref={panelRef}>
    {open && <div ref={dialogRef} id="corner-quick-panel" className="corner-quick-panel" role="dialog" aria-modal="false" aria-labelledby="corner-quick-title" tabIndex="-1">
      <div id="corner-quick-title" className="corner-quick-title">Acesso rápido</div>
      <Link to="/" onClick={close} data-testid="corner-quick-home"><span>Voltar ao início</span><ArrowRight size={15}/></Link>
      <Link to="/como-funciona" onClick={close} data-testid="corner-quick-how"><span>Como funciona</span><ArrowRight size={15}/></Link>
      <Link to="/recursos" onClick={close} data-testid="corner-quick-resources"><span>Recursos</span><ArrowRight size={15}/></Link>
      <Link to="/ajuda" onClick={close} data-testid="corner-quick-help"><span>Ajuda</span><ArrowRight size={15}/></Link>
      <Link className="corner-quick-urgent" to="/preciso-ajuda" onClick={close} data-testid="corner-quick-urgent"><span>Preciso de ajuda agora</span><ArrowRight size={15}/></Link>
    </div>}
    <button ref={triggerRef} type="button" className="corner-logo" onClick={() => setOpen(value => !value)} aria-label={open ? "Fechar acesso rápido" : "Abrir acesso rápido"} aria-expanded={open} aria-controls="corner-quick-panel" aria-haspopup="dialog" data-testid="corner-brand-button"><span className="corner-logo-glow" aria-hidden="true"/><span className="corner-logo-float" aria-hidden="true"><span className="corner-logo-body"><span className="corner-logo-mark"><BrandMark size={30}/></span></span></span><span className="corner-logo-tooltip">Acesso rápido</span></button>
  </div>;
}
function Header() {
  const [open, setOpen] = useState(false);
  const [more, setMore] = useState(false);
  const menuRef = useRef(null);
  const menuButtonRef = useRef(null);
  const wasOpenRef = useRef(false);
  const { user } = useAuth();
  useEffect(() => {
    if (!open) {
      if (wasOpenRef.current) menuButtonRef.current?.focus();
      wasOpenRef.current = false;
      return undefined;
    }
    wasOpenRef.current = true;
    const menu = menuRef.current;
    if (menu) menu.id = "main-navigation";
    const focusable = () => menu?.querySelectorAll("a[href], button:not([disabled])") || [];
    const first = focusable()[0];
    first?.focus();
    const handleKeyDown = event => {
      if (event.key === "Escape") {
        event.preventDefault();
        setOpen(false);
        setMore(false);
        return;
      }
      if (event.key !== "Tab") return;
      const items = [...focusable()];
      if (!items.length) return;
      const firstItem = items[0];
      const lastItem = items[items.length - 1];
      if (event.shiftKey && document.activeElement === firstItem) {
        event.preventDefault();
        lastItem.focus();
      } else if (!event.shiftKey && document.activeElement === lastItem) {
        event.preventDefault();
        firstItem.focus();
      }
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [open]);
  return <header className="site-header">{open && <div className="nav-backdrop" onClick={() => { setOpen(false); setMore(false); }} aria-hidden="true"/>}<div className="nav-wrap"><Logo /><nav ref={menuRef} className={open ? "nav-links open" : "nav-links"} role={open ? "dialog" : undefined} aria-modal={open ? "true" : undefined} aria-label={open ? "Menu principal" : undefined} data-testid="main-navigation" onClick={() => setOpen(false)}><div className="nav-drawer-head"><Logo/><div className="nav-drawer-actions" onClick={e => e.stopPropagation()}><ThemeToggle/><button className="nav-drawer-close" onClick={() => { setOpen(false); setMore(false); }} aria-label="Fechar menu" data-testid="drawer-close-button"><X size={22}/></button></div></div><Link to="/como-funciona" data-testid="nav-how">Como funciona</Link><Link to="/para-estudantes" data-testid="nav-students">Para estudantes</Link><Link to="/profissionais" data-testid="nav-pros">Para profissionais</Link><Link to="/instituicoes" data-testid="nav-schools">Para instituições</Link><div className="nav-more"><button className="nav-more-button" onClick={e => { e.stopPropagation(); setMore(!more); }} aria-expanded={more} data-testid="nav-more-button">Mais <ChevronDown size={14}/></button><div className={more ? "nav-more-menu open" : "nav-more-menu"}><Link to="/recursos" data-testid="nav-resources">Recursos</Link><Link to="/ajuda" data-testid="nav-help">Ajuda</Link><Link to="/privacidade" data-testid="nav-privacy">Privacidade</Link><Link to="/termos" data-testid="nav-terms">Termos</Link></div></div><div className="nav-drawer-foot"><Link to="/entrar" className="button primary full" data-testid="drawer-talk-button">Quero conversar <ArrowRight size={16}/></Link><span><ShieldCheck size={14}/> Piloto institucional · atendimento conforme a equipe vinculada</span></div></nav><ThemeToggle /><PilotAccessLink /><Link to="/entrar" className="header-cta" data-testid="header-talk-button">Quero conversar <ArrowRight size={16}/></Link><button ref={menuButtonRef} className="icon-button mobile-menu" onClick={() => setOpen(!open)} aria-label={open ? "Fechar menu" : "Abrir menu"} aria-expanded={open} aria-controls="main-navigation" data-testid="mobile-menu-button">{open ? <X/> : <Menu/>}</button></div></header>;
}
function PilotAccessLink() {
  const { user } = useMvpAuth();
  if (user) return <Link to={HOME_BY_ROLE[user.role] || "/"} className="header-login" data-testid="header-account-button">Minha área</Link>;
  return <Link to="/entrar" className="header-login" data-testid="header-login-button">Entrar</Link>;
}
function SkipLink() { const location = useLocation(); useLayoutEffect(() => { const main = document.querySelector("main"); if (main) main.id = "main-content"; const nav = document.querySelector('[data-testid="main-navigation"]'); if (nav) nav.id = "main-navigation"; }, [location.pathname, location.search]); return <a className="skip-link" href="#main-content" data-testid="skip-link">Ir para o conteúdo</a>; }
function Footer() { return <footer className="footer"><div className="footer-main"><div><Logo/><p>Um primeiro passo para cuidar de você.</p><span className="footer-badge">Piloto institucional</span></div><div className="footer-links"><div className="footer-group"><span className="footer-group-title">Conhecer</span><Link to="/como-funciona" data-testid="footer-how">Como funciona</Link><Link to="/para-estudantes" data-testid="footer-students">Para estudantes</Link><Link to="/profissionais" data-testid="footer-pros">Para profissionais</Link><Link to="/instituicoes" data-testid="footer-schools">Para instituições</Link></div><div className="footer-group"><span className="footer-group-title">Apoio e segurança</span><Link to="/recursos" data-testid="footer-resources">Recursos</Link><Link to="/ajuda" data-testid="footer-help">Ajuda</Link><Link to="/ajuda/instituicoes" data-testid="footer-institution-guide">Guia para instituições</Link><Link to="/preciso-ajuda" data-testid="footer-emergency">Preciso de ajuda agora</Link></div><div className="footer-group"><span className="footer-group-title">Informações</span><Link to="/privacidade" data-testid="footer-privacy">Privacidade</Link><Link to="/termos" data-testid="footer-terms">Termos</Link></div></div></div><div className="footer-bottom"><span>Atendimento conforme a equipe vinculada · não é serviço de emergência.</span><span>© Acolhe · 2026</span></div></footer>; }
function MarketingLayout({ children }) { return <><Header/>{children}<Footer/><CornerLogo/></>; }
