  const p = professionals.find(x => x.id === professionalId) || professionals[0];
  const duration = demoDurations[durationIndex];
  const rows = [["Como eu estava", moods.length ? moods.join(" · ") : "Não informado"], ["Sobre o que escolhi conversar", topicLabel || "Não escolhido"], ["Profissional", `${p.name} · perfil de referência`], ["Duração", confirmed ? confirmed.duration : duration.label], ["Data", confirmed ? `${confirmed.day} · ${confirmed.time}` : "De referência"], ["Próximo passo", "Definido durante a conversa"]];
